class Solution:
    def minimumCost(self, s, encCost, flatCost):
        n = len(s)
        pre = [0] * (n + 1)
        for i, ch in enumerate(s):
            pre[i+1] = pre[i] + (ch == '1')
        dp = [0] * max(n, 1)
        L = 1
        while L <= n:
            nd = [0] * (n - L + 1)
            for l in range(n - L + 1):
                x = pre[l+L] - pre[l]
                best = flatCost if x == 0 else L * x * encCost
                if L > 1 and L % 2 == 0:
                    best = min(best, dp[l] + dp[l + L // 2])
                nd[l] = best
            dp = nd
            L *= 2
        return dp[0]

