class Solution {
public:
    long long minimumCost(string s, int encCost, int flatCost) {
        int n = s.size();
        vector<long long> pre(n + 1, 0);
        for (int i = 0; i < n; i++) pre[i+1] = pre[i] + (s[i] == '1');
        vector<long long> dp(max(n, 1), 0);
        for (int L = 1; L <= n; L <<= 1) {
            vector<long long> nd(n - L + 1);
            for (int l = 0; l + L <= n; l++) {
                long long x = pre[l+L] - pre[l];
                long long best = (x == 0) ? (long long)flatCost : (long long)L * x * encCost;
                if (L > 1) best = min(best, dp[l] + dp[l + L/2]);
                nd[l] = best;
            }
            dp = nd;
        }
        return dp[0];
    }
};

