class Solution {
    public long minimumCost(String s, int encCost, int flatCost) {
        int n = s.length();
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i+1] = pre[i] + (s.charAt(i) == '1' ? 1 : 0);
        long[] dp = new long[Math.max(n, 1)];
        for (int L = 1; L <= n; L <<= 1) {
            long[] nd = new long[n - L + 1];
            for (int l = 0; l + L <= n; l++) {
                long x = pre[l+L] - pre[l];
                long best = (x == 0) ? flatCost : (long)L * x * encCost;
                if (L > 1) best = Math.min(best, dp[l] + dp[l + L/2]);
                nd[l] = best;
            }
            dp = nd;
        }
        return dp[0];
    }
}

