var minimumCost = function(s, encCost, flatCost) {
    const n = s.length;
    const pre = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) pre[i+1] = pre[i] + (s[i] === '1' ? 1 : 0);
    let dp = new Array(Math.max(n, 1)).fill(0);
    for (let L = 1; L <= n; L *= 2) {
        const nd = new Array(n - L + 1);
        for (let l = 0; l + L <= n; l++) {
            const x = pre[l+L] - pre[l];
            let best = x === 0 ? flatCost : L * x * encCost;
            if (L > 1) best = Math.min(best, dp[l] + dp[l + L/2]);
            nd[l] = best;
        }
        dp = nd;
    }
    return dp[0];
};
